package br.app.criati.financeiro.web;
import java.math.BigDecimal; import java.time.*; import java.util.*; import br.app.criati.financeiro.model.*; import br.app.criati.shared.enums.*;
public record CompraCartaoResponse(UUID id,UUID cartaoId,String cartaoNome,UUID cartaoPrincipalId,String cartaoPrincipalNome,UUID pessoaResponsavelId,String pessoaResponsavelNome,UUID categoriaId,String categoriaNome,UUID parteFinanceiraId,String parteFinanceiraNome,String descricao,LocalDate dataCompra,BigDecimal valorTotal,int quantidadeParcelas,StatusCompraCartao status,String observacao,String motivoCancelamento,OffsetDateTime canceladoEm,String motivoEstorno,OffsetDateTime estornadoEm,List<ParcelaResponse> parcelas){
 public static CompraCartaoResponse from(CompraCartao c){return new CompraCartaoResponse(c.getId(),c.getCartao().getId(),c.getCartao().getNome(),c.getCartaoPrincipal().getId(),c.getCartaoPrincipal().getNome(),c.getPessoaResponsavel().getId(),c.getPessoaResponsavel().getNome(),c.getCategoria().getId(),c.getCategoria().getNome(),c.getParteFinanceira()==null?null:c.getParteFinanceira().getId(),c.getParteFinanceira()==null?null:c.getParteFinanceira().getNome(),c.getDescricao(),c.getDataCompra(),c.getValorTotal(),c.getQuantidadeParcelas(),c.getStatus(),c.getObservacao(),c.getMotivoCancelamento(),c.getCanceladoEm(),c.getMotivoEstorno(),c.getEstornadoEm(),c.getParcelas().stream().map(ParcelaResponse::from).toList());}
 public record ParcelaResponse(UUID id,int numero,int totalParcelas,BigDecimal valor,LocalDate competencia,StatusParcelaCartao status,UUID faturaId){static ParcelaResponse from(ParcelaCompraCartao p){return new ParcelaResponse(p.getId(),p.getNumero(),p.getTotalParcelas(),p.getValor(),p.getCompetencia(),p.getStatus(),p.getFaturaId());}}
}
